/**
 * Unit tests for the `--diagnose` dump reader.
 *
 * The dump text is generated by calling the REAL formatter
 * (`formatFSE26Diagnostic`) rather than by pasting a copy of its output. A
 * pasted fixture would only prove that this parser agrees with a snapshot of
 * the format; driving the producer means a format change fails here instead of
 * silently parsing nothing in production.
 *
 * @module benchmarks/__tests__/fse26-diagnose-analyze
 */

import { describe, expect, it } from 'vitest';

import type { MetricDiagnostic } from '../../packages/core/src/index.js';
import { formatFSE26Diagnostic } from '../../packages/kinetic/src/benchmarks/index.js';
import {
  computeEdgeLatencyScores,
  DEFAULT_LAT_MIN_RISE,
  DEFAULT_LAT_WEIGHT,
  DEFAULT_POOL_METRIC_PENALTY_WEIGHT,
  POOL_METRIC_PREFIX,
} from '../../packages/tree/src/index.js';

import type { DiagnosedCase, WeightSeparationCase } from '../src/fse26-diagnose-analyze.js';
import {
  anomalyShape,
  buildWeightSeparationCases,
  caseWeightInterval,
  classifyMiss,
  computeWeightSeparation,
  computeZeroRegressionWindow,
  diffDiagnostics,
  familyCompetition,
  formatAnalyzeSections,
  formatAnomalyShapeReport,
  formatDiagnoseComparison,
  formatMetricCompetitionReport,
  formatMissReport,
  formatWeightSeparationReport,
  formatZeroRegressionWindowReport,
  isTop1Correct,
  latencySlopes,
  MISS_DECIDED_BY,
  MISS_ORDER,
  parseAnalyzeArgs,
  parseDiagnosticDump,
  regressionMechanism,
  tallyDeltas,
  zeroRegressionSamples,
} from '../src/fse26-diagnose-analyze.js';

interface ServiceSpec {
  serviceId: string;
  selfAnomaly?: number;
  logScore?: number;
  /** The failed-edge-direction score (the log score's INVERSE). */
  failedEdge?: number;
  failedEdgeRecords?: number;
  latRise?: number;
  latEdges?: number;
  http?: number;
  logic?: number;
  dominant?: string | undefined;
  /**
   * Typed with the engine's own vocabulary rather than `string`: a test that can
   * spell an outcome the engine cannot produce is testing a format that does not
   * exist. Tolerance of a NEW reason is exercised by tampering with a real dump.
   */
  metricOutcomes?: readonly MetricDiagnostic[];
}

function serviceLine(spec: ServiceSpec) {
  return {
    serviceId: spec.serviceId,
    metricNames: [`cpu`, `memory`],
    dominantMetric: 'dominant' in spec ? spec.dominant : 'cpu',
    selfAnomaly: spec.selfAnomaly ?? 0.5,
    logScore: spec.logScore ?? 0,
    failedEdgeScore: spec.failedEdge ?? 0,
    failedEdgeRecords: spec.failedEdgeRecords ?? 0,
    latRise: spec.latRise,
    latEdges: spec.latEdges ?? 0,
    errorCount: (spec.logic ?? 0) + (spec.http ?? 0),
    fatalCount: 0,
    logicExceptionCount: spec.logic ?? 0,
    httpExceptionCount: spec.http ?? 0,
    sampleErrorMessages: [],
    exceptionClasses: [],
    metricOutcomes: spec.metricOutcomes,
  };
}

/** Render one diagnostic block through the real formatter. */
function dump(overrides: Partial<Parameters<typeof formatFSE26Diagnostic>[0]> = {}): string {
  return formatFSE26Diagnostic({
    datapack: 'dp-1',
    faultType: 'JVMMemoryStress',
    groundTruthServices: ['ts-order-service'],
    services: [],
    topPredictions: [],
    logSignalMode: 'logicHttp',
    ...overrides,
  });
}

describe('parseDiagnosticDump', () => {
  it('reads a block produced by the real formatter', () => {
    const text = dump({
      services: [
        serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.257, http: 0, logic: 0 }),
        serviceLine({ serviceId: 'ts-ui', selfAnomaly: 0.9, http: 412, logic: 3 }),
      ],
      topPredictions: ['ts-ui', 'ts-order-service'],
    });

    const cases = parseDiagnosticDump(text);

    expect(cases).toHaveLength(1);
    const kase = cases[0]!;
    expect(kase.datapack).toBe('dp-1');
    expect(kase.faultType).toBe('JVMMemoryStress');
    expect(kase.groundTruth).toEqual(['ts-order-service']);
    expect(kase.logSignalMode).toBe('logicHttp');
    expect(kase.prediction).toEqual(['ts-ui', 'ts-order-service']);
    expect(kase.services.map((s) => s.serviceId)).toEqual(['ts-ui', 'ts-order-service']);

    const ui = kase.services.find((s) => s.serviceId === 'ts-ui')!;
    expect(ui.isGroundTruth).toBe(false);
    expect(ui.predictedRank).toBe(1);
    expect(ui.httpExceptionCount).toBe(412);
    expect(ui.logicExceptionCount).toBe(3);
    expect(ui.selfAnomaly).toBeCloseTo(0.9, 6);

    const order = kase.services.find((s) => s.serviceId === 'ts-order-service')!;
    expect(order.isGroundTruth).toBe(true);
    expect(order.predictedRank).toBe(2);
    expect(order.httpExceptionCount).toBe(0);
  });

  it('ignores the surrounding log noise', () => {
    const text = [
      "Micro-Kinetic — FSE'26 RCABench",
      'Config: logWeight=1 logMode=logicHttp rankNormalization=true',
      dump({ datapack: 'dp-a' }),
      '  Per-fault-type Top@1:',
      '    JVMMemoryStress  4/171  2.3%',
      dump({ datapack: 'dp-b' }),
    ].join('\n');

    expect(parseDiagnosticDump(text).map((c) => c.datapack)).toEqual(['dp-a', 'dp-b']);
  });

  it('drops a truncated block rather than reporting a partial service list', () => {
    const full = dump({ services: [serviceLine({ serviceId: 'ts-ui', http: 5 })] });
    const truncated = full.slice(0, full.indexOf('  prediction='));

    expect(parseDiagnosticDump(truncated)).toEqual([]);
  });

  it('keeps a candidate whose service id is EMPTY, and counts it', () => {
    // One row per case carries no service name on the shipped dump — the ten
    // unlabelled `k8s.*` series. An id-requiring regex dropped it silently, and the
    // drop is not cosmetic: the engine's metric term divides by `n - 1` over ITS
    // candidate set, so a reader that parses one row fewer computes a different metric
    // term for every service in the case.
    const text = dump({
      services: [
        serviceLine({ serviceId: '', selfAnomaly: 0.1 }),
        serviceLine({ serviceId: 'ts-ui', selfAnomaly: 0.9 }),
      ],
    });

    const kase = parseDiagnosticDump(text)[0]!;
    expect(kase.services.map((s) => s.serviceId)).toEqual(['ts-ui', '']);
    expect(kase.services).toHaveLength(2);
  });

  it('drops a block whose parsed candidate count disagrees with its own header', () => {
    // A short list is not a smaller case: it is a different `n`, which changes the
    // metric term of every service in the case. An absent case shows up in the totals;
    // a wrong one does not.
    const text = dump({ services: [serviceLine({ serviceId: 'ts-ui' })] }).replace(
      'services=1',
      'services=2',
    );

    expect(parseDiagnosticDump(text)).toEqual([]);
  });

  it('records an absent log mode as an empty string, so it can be detected', () => {
    // Older dumps predate the mode field. Parsing must not fail, and the
    // sentinel has to be distinguishable from a real mode.
    const legacy = dump().replace(' logMode=logicHttp', '');
    const kase = parseDiagnosticDump(legacy)[0]!;
    expect(kase.logSignalMode).toBe('');
  });

  it('reads the latency fields, and the dash as UNKNOWN rather than as 1', () => {
    // The producer prints `-` when no caller measured a change. Parsing that as 1
    // would claim every caller measured an identical latency.
    const text = dump({
      services: [
        serviceLine({ serviceId: 'ts-src', latRise: 4.25, latEdges: 2 }),
        serviceLine({ serviceId: 'ts-win' }),
      ],
    });
    const parsed = parseDiagnosticDump(text)[0]!.services;
    const src = parsed.find((s) => s.serviceId === 'ts-src')!;
    const win = parsed.find((s) => s.serviceId === 'ts-win')!;
    expect(src.latRise).toBe(4.25);
    expect(src.latEdges).toBe(2);
    expect(win.latRise).toBeUndefined();
    expect(win.latEdges).toBe(0);
  });

  it('reports the latency fields as undefined for a dump that predates them', () => {
    const legacy = dump({ services: [serviceLine({ serviceId: 'ts-src' })] }).replace(
      / latRise=\S+ latEdges=\d+/,
      '',
    );
    expect(legacy).not.toContain('latRise=');
    const src = parseDiagnosticDump(legacy)[0]!.services[0]!;
    expect(src.latRise).toBeUndefined();
    expect(src.latEdges).toBeUndefined();
  });

  it('reads the call graph as written, and reports an ABSENT graph as undefined', () => {
    // "not recorded" must stay distinguishable from "recorded and empty": a
    // structural answer computed from a defaulted empty graph would call every
    // service unconnected.
    const text = dump({
      services: [serviceLine({ serviceId: 'ts-src' })],
      edges: ['ts-a>ts-b', 'ts-b>ts-a'],
    });
    expect(parseDiagnosticDump(text)[0]!.edges).toEqual(['ts-a>ts-b', 'ts-b>ts-a']);

    const withoutGraph = dump({ services: [serviceLine({ serviceId: 'ts-src' })] });
    expect(parseDiagnosticDump(withoutGraph)[0]!.edges).toBeUndefined();
  });

  it('reads the failed-edge fields when the dump carries them', () => {
    const text = dump({
      services: [serviceLine({ serviceId: 'ts-order-service', failedEdge: 1 })],
    });
    const entry = parseDiagnosticDump(text)[0]!.services[0]!;
    expect(entry.failedEdgeScore).toBe(1);
    expect(entry.failedEdgeRecords).toBe(0);
  });

  it('records an absent failed-edge field as UNKNOWN, not as zero', () => {
    // The whole point of this analyzer is comparing dumps across runs, so it has
    // to read a dump written before the engine reported the field at all.
    // Defaulting to 0 would claim the service was measured and credited
    // nothing — a different statement from "this dump cannot answer that", and
    // the wrong one to build a regression verdict on.
    const withField = dump({
      services: [serviceLine({ serviceId: 'ts-order-service', failedEdge: 1 })],
    });
    expect(withField).toContain('failedEdge=1.000');
    const legacy = withField.replace(/ failedEdge=\S+ failedEdgeRecords=\d+/, '');
    expect(legacy).not.toContain('failedEdge=');
    const entry = parseDiagnosticDump(legacy)[0]!.services[0]!;
    expect(entry.failedEdgeScore).toBeUndefined();
    expect(entry.failedEdgeRecords).toBeUndefined();
  });

  it('reads a service with no markers and an absent dominant metric', () => {
    const text = dump({
      services: [serviceLine({ serviceId: 'ts-unknown', dominant: undefined })],
    });
    const entry = parseDiagnosticDump(text)[0]!.services[0]!;
    expect(entry.isGroundTruth).toBe(false);
    expect(entry.predictedRank).toBeUndefined();
  });

  it('reads a multi-service ground truth list', () => {
    const text = dump({ groundTruthServices: ['ts-a', 'ts-b'] });
    expect(parseDiagnosticDump(text)[0]!.groundTruth).toEqual(['ts-a', 'ts-b']);
  });

  it('returns nothing for text with no block', () => {
    expect(parseDiagnosticDump('no diagnostics here\n')).toEqual([]);
  });
});

describe('isTop1Correct', () => {
  const kase = (prediction: string[]): DiagnosedCase => ({
    datapack: 'dp',
    faultType: 'JVMMemoryStress',
    groundTruth: ['ts-order-service'],
    logSignalMode: 'logicHttp',
    edges: undefined,
    services: [],
    prediction,
  });

  it('accepts the ground truth at rank 1', () => {
    expect(isTop1Correct(kase(['ts-order-service']))).toBe(true);
  });

  it('rejects the ground truth at rank 2', () => {
    expect(isTop1Correct(kase(['ts-ui', 'ts-order-service']))).toBe(false);
  });

  it('rejects an empty prediction', () => {
    expect(isTop1Correct(kase([]))).toBe(false);
  });
});

describe('diffDiagnostics', () => {
  function kase(
    datapack: string,
    prediction: string[],
    faultType = 'JVMMemoryStress',
  ): DiagnosedCase {
    return {
      datapack,
      faultType,
      groundTruth: ['ts-order-service'],
      logSignalMode: 'logicHttp',
      edges: undefined,
      services: [],
      prediction,
    };
  }

  it('classifies each case against the baseline', () => {
    const before = [
      kase('a', ['ts-order-service']),
      kase('b', ['ts-ui']),
      kase('c', ['ts-order-service']),
      kase('d', ['ts-ui']),
    ];
    const after = [
      kase('a', ['ts-order-service']),
      kase('b', ['ts-order-service']),
      kase('c', ['ts-ui']),
      kase('d', ['ts-auth-service']),
    ];

    const deltas = diffDiagnostics(before, after);

    expect(deltas.map((d) => [d.datapack, d.kind])).toEqual([
      ['a', 'both-correct'],
      ['b', 'gained'],
      ['c', 'regressed'],
      ['d', 'both-wrong'],
    ]);
    expect(deltas[2]!.top1Before).toBe('ts-order-service');
    expect(deltas[2]!.top1After).toBe('ts-ui');
    expect(tallyDeltas(deltas)).toEqual({
      regressed: 1,
      gained: 1,
      'both-correct': 1,
      'both-wrong': 1,
    });
  });

  it('skips cases the other dump does not contain', () => {
    const deltas = diffDiagnostics(
      [kase('a', ['ts-ui']), kase('b', ['ts-ui'])],
      [kase('b', ['ts-order-service'])],
    );
    expect(deltas.map((d) => d.datapack)).toEqual(['b']);
  });
});

describe('regressionMechanism', () => {
  const delta = {
    datapack: 'dp',
    faultType: 'JVMMemoryStress',
    kind: 'regressed' as const,
    groundTruth: ['ts-order-service'],
    top1Before: 'ts-order-service',
    top1After: 'ts-ui',
  };

  function kaseWith(services: DiagnosedCase['services']): DiagnosedCase {
    return {
      datapack: 'dp',
      faultType: 'JVMMemoryStress',
      groundTruth: ['ts-order-service'],
      logSignalMode: 'logicHttp',
      edges: undefined,
      services,
      prediction: ['ts-ui', 'ts-order-service'],
    };
  }

  const svc = (serviceId: string, http: number, logic: number, selfAnomaly: number) => ({
    serviceId,
    isGroundTruth: serviceId === 'ts-order-service',
    predictedRank: undefined,
    selfAnomaly,
    logScore: 0,
    failedEdgeScore: 0,
    failedEdgeRecords: 0,
    latRise: undefined,
    latEdges: 0,
    dominantMetric: '',
    errorCount: http + logic,
    fatalCount: 0,
    logicExceptionCount: logic,
    httpExceptionCount: http,
    metricOutcomes: undefined,
  });

  it('recognises a silent source out-flooded by its caller', () => {
    const mechanism = regressionMechanism(delta, [
      kaseWith([svc('ts-order-service', 0, 0, 0.26), svc('ts-ui', 412, 0, 0.9)]),
    ]);
    expect(mechanism.winnerOutfloodsSource).toBe(true);
    expect(mechanism.sourceHttpCount).toBe(0);
    expect(mechanism.winnerHttpCount).toBe(412);
  });

  it('does not claim the mechanism when the source floods too', () => {
    const mechanism = regressionMechanism(delta, [
      kaseWith([svc('ts-order-service', 90, 0, 0.8), svc('ts-ui', 412, 0, 0.9)]),
    ]);
    expect(mechanism.winnerOutfloodsSource).toBe(false);
  });

  it('marks an absent ground-truth name rather than leaving the column empty', () => {
    const mechanism = regressionMechanism({ ...delta, groundTruth: [] }, [
      kaseWith([svc('ts-ui', 412, 0, 0.9)]),
    ]);
    expect(mechanism.groundTruth).toBe('-');
  });

  it('reports undefined when the source is absent from the case', () => {
    const mechanism = regressionMechanism(delta, [kaseWith([svc('ts-ui', 412, 0, 0.9)])]);
    expect(mechanism.sourceHttpCount).toBeUndefined();
    expect(mechanism.winnerOutfloodsSource).toBe(false);
  });

  it('reports undefined when the case is absent from the dump', () => {
    const mechanism = regressionMechanism(delta, []);
    expect(mechanism.winnerHttpCount).toBeUndefined();
    expect(mechanism.winnerOutfloodsSource).toBe(false);
  });
});

describe('formatDiagnoseComparison', () => {
  it('reports the tally, the per-type table and the mechanism count', () => {
    const before = parseDiagnosticDump(
      dump({
        datapack: 'dp-1',
        services: [serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.9 })],
        topPredictions: ['ts-order-service'],
      }),
    );
    const after = parseDiagnosticDump(
      dump({
        datapack: 'dp-1',
        services: [
          serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.26, http: 0 }),
          serviceLine({ serviceId: 'ts-ui', selfAnomaly: 0.9, http: 412 }),
        ],
        topPredictions: ['ts-ui', 'ts-order-service'],
      }),
    );

    const report = formatDiagnoseComparison(before, after, 'count -> logicHttp');

    expect(report).toContain("FSE'26 diagnostic comparison — count -> logicHttp");
    expect(report).toContain('after-mode: logicHttp');
    expect(report).toContain('cases compared: 1   regressed: 1   gained: 0');
    expect(report).toContain('JVMMemoryStress');
    expect(report).toContain('dp-1');
    expect(report).toContain('ts-order-service');
    // The silent source (0) against the flooding caller (412) is the claim.
    expect(report).toMatch(/0\/0\s+412\/0\s+YES/);
    expect(report).toContain(
      "Mechanism 'the winner is a victim flooding framework HTTP while the source emits none': 1/1 regressions.",
    );
    expect(report).not.toContain('need a different explanation');
  });

  it('flags a regression the mechanism does not explain', () => {
    const before = parseDiagnosticDump(
      dump({
        services: [serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.9 })],
        topPredictions: ['ts-order-service'],
      }),
    );
    const after = parseDiagnosticDump(
      dump({
        services: [
          // The source floods as much as the winner: not the silent-source case.
          serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.26, http: 500 }),
          serviceLine({ serviceId: 'ts-ui', selfAnomaly: 0.9, http: 412 }),
        ],
        topPredictions: ['ts-ui', 'ts-order-service'],
      }),
    );

    const report = formatDiagnoseComparison(before, after, 'count -> logicHttp');

    expect(report).toMatch(/500\/0\s+412\/0\s+no/);
    expect(report).toContain('0/1 regressions');
    expect(report).toContain('1 regression(s) need a different explanation');
  });

  it('says so explicitly when nothing regressed', () => {
    const before = parseDiagnosticDump(
      dump({ services: [serviceLine({ serviceId: 'ts-order-service' })] }),
    );
    const report = formatDiagnoseComparison(before, before, 'count -> count');

    expect(report).toContain('regressed: 0');
    expect(report).toContain('No regressions');
    expect(report).not.toContain('Regressions (');
  });

  it('marks an unrecorded mode rather than printing an empty one', () => {
    const legacy = parseDiagnosticDump(dump().replace(' logMode=logicHttp', ''));
    expect(formatDiagnoseComparison(legacy, legacy, 'x -> y')).toContain(
      'after-mode: (unrecorded)',
    );
  });
});

describe('formatDiagnoseComparison — degenerate rows', () => {
  it('renders a regression whose candidate run predicted nothing', () => {
    // "Wrong" includes "predicted nothing", so `top1After` is the one field a
    // regression row can be missing. The row must mark it rather than print a
    // blank, and the source/winner counts are absent with it because neither
    // service is named.
    const before = parseDiagnosticDump(
      dump({
        services: [serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.9 })],
        topPredictions: ['ts-order-service'],
      }),
    );
    const after = parseDiagnosticDump(
      dump({ services: [serviceLine({ serviceId: 'ts-ui', http: 3 })], topPredictions: [] }),
    );

    const report = formatDiagnoseComparison(before, after, 'x -> y');

    expect(report).toContain('Regressions (');
    expect(report).toMatch(/ts-order-service→-\s+-\/-\s+-\/-\s+no/);
    expect(report).toContain('0/1 regressions');
  });

  it('counts a gained case in the per-fault-type table', () => {
    const wrong = dump({ datapack: 'dp-gain', services: [], topPredictions: ['ts-ui'] });
    const right = dump({ datapack: 'dp-gain', services: [], topPredictions: ['ts-order-service'] });

    const report = formatDiagnoseComparison(
      parseDiagnosticDump(wrong),
      parseDiagnosticDump(right),
      'x -> y',
    );

    expect(report).toContain('gained: 1');
    expect(report).toMatch(/JVMMemoryStress\s+1\s+0\s+1/);
  });
});

describe('parseDiagnosticDump — metric competition', () => {
  const withCompetition = (spec: ServiceSpec) =>
    dump({ services: [serviceLine(spec)], topPredictions: [spec.serviceId] });

  it('reads the metric outcomes and the dominant metric of a service', () => {
    const text = withCompetition({
      serviceId: 'ts-order-service',
      dominant: 'container.memory.rss',
      metricOutcomes: [
        { label: 'container.memory.rss', outcome: 'kept', score: 0.412 },
        { label: 'jvm.memory.used', outcome: 'transient-return', score: 0 },
      ],
    });

    const entry = parseDiagnosticDump(text)[0]!.services[0]!;

    expect(entry.dominantMetric).toBe('container.memory.rss');
    expect(entry.metricOutcomes).toEqual([
      { label: 'container.memory.rss', outcome: 'kept', score: 0.412 },
      { label: 'jvm.memory.used', outcome: 'transient-return', score: 0 },
    ]);
  });

  it('reports an absent dominant metric as an empty string, not as the placeholder', () => {
    const text = withCompetition({ serviceId: 'ts-order-service', dominant: undefined });
    expect(parseDiagnosticDump(text)[0]!.services[0]!.dominantMetric).toBe('');
  });

  it('reports no metric outcomes when the block carried none', () => {
    // A dump from an engine that does not report the competition must read as
    // "unreported", never as "this service carries no metrics".
    const text = withCompetition({ serviceId: 'ts-order-service' });
    expect(parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes).toBeUndefined();
  });

  it('discards an inventory whose declared size disagrees with the entries printed', () => {
    // A truncated list reads exactly like a complete one, and a parser that
    // accepted one once fabricated `gt_http = 0` for every replace-code case.
    // The block declares the size, so the parser can refuse.
    const text = withCompetition({
      serviceId: 'ts-order-service',
      metricOutcomes: [
        { label: 'container.memory.rss', outcome: 'kept', score: 0.412 },
        { label: 'jvm.memory.used', outcome: 'kept', score: 0.2 },
      ],
    }).replace('metricKept(2):', 'metricKept(7):');

    expect(parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes).toBeUndefined();
  });

  it('discards an inventory carrying a non-finite score', () => {
    const text = withCompetition({
      serviceId: 'ts-order-service',
      metricOutcomes: [{ label: 'container.memory.rss', outcome: 'kept', score: Number.NaN }],
    });

    expect(parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes).toBeUndefined();
  });

  it('does not fabricate an inventory when only the dropped line survived', () => {
    // A lost `metricKept` line would otherwise leave a dropped-only list whose
    // length matches its own declared count — a truncation that reads as a
    // complete inventory, which is exactly how the earlier parser fabricated
    // `gt_http = 0` for every replace-code case.
    const text = dump({
      services: [
        serviceLine({
          serviceId: 'ts-ui',
          metricOutcomes: [
            { label: 'container.memory.rss', outcome: 'transient-return', score: 0 },
          ],
        }),
      ],
      topPredictions: ['ts-ui'],
    });

    expect(text).toContain('metricKept(0):');
    expect(text).toContain('metricDrop(1): container.memory.rss:transient-return');
    // Drop the kept line outright, so the dropped line has nothing to append to.
    const withoutKept = text
      .split('\n')
      .filter((line) => !line.startsWith('    metricKept('))
      .join('\n');

    expect(parseDiagnosticDump(withoutKept)[0]!.services[0]!.metricOutcomes).toBeUndefined();
  });

  it('discards an inventory whose label split the line into extra entries', () => {
    // A label containing a space would otherwise be read as two metrics, and the
    // declared-count check is what catches it.
    const text = dump({
      services: [
        serviceLine({
          serviceId: 'ts-ui',
          metricOutcomes: [{ label: 'two words', outcome: 'kept', score: 0.5 }],
        }),
      ],
      topPredictions: ['ts-ui'],
    });

    expect(text).toContain('metricKept(1): two words=0.500');
    expect(parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes).toBeUndefined();
  });

  it('keeps an outcome word it does not recognise instead of dropping the metric', () => {
    // The reader must survive an engine that adds a guard. Discarding an unknown
    // word would shorten the inventory below its declared size, and mapping it to
    // `kept` would silently promote a discarded metric into the competition.
    const text = withCompetition({
      serviceId: 'ts-order-service',
      metricOutcomes: [{ label: 'container.memory.rss', outcome: 'transient-return', score: 0 }],
    }).replace('container.memory.rss:transient-return', 'container.memory.rss:brand-new-guard');

    const entry = parseDiagnosticDump(text)[0]!.services[0]!;

    expect(entry.metricOutcomes).toEqual([
      { label: 'container.memory.rss', outcome: 'brand-new-guard', score: 0 },
    ]);
  });

  it('does not attach a metric inventory to the following service', () => {
    // The formatter reorders services by anomaly score, so the metric lines can
    // trail a service that is not the one the inventory belongs to if the
    // parser keys on position instead of on the service it last read.
    const text = dump({
      services: [
        serviceLine({
          serviceId: 'ts-ui',
          selfAnomaly: 0.9,
          metricOutcomes: [{ label: 'http', outcome: 'kept', score: 1 }],
        }),
        serviceLine({ serviceId: 'ts-next', selfAnomaly: 0.2 }),
      ],
      topPredictions: ['ts-ui', 'ts-next'],
    });

    const services = parseDiagnosticDump(text)[0]!.services;
    expect(services.map((s) => s.serviceId)).toEqual(['ts-ui', 'ts-next']);
    expect(services[0]!.metricOutcomes).toHaveLength(1);
    expect(services[1]!.metricOutcomes).toBeUndefined();
  });
});

describe('familyCompetition', () => {
  const MEMORY = { label: 'memory', pattern: /memory/i };
  const caseWith = (faultType: string, services: ServiceSpec[]): DiagnosedCase =>
    parseDiagnosticDump(
      dump({
        faultType,
        groundTruthServices: services.map((s) => s.serviceId),
        services: services.map(serviceLine),
        topPredictions: services.map((s) => s.serviceId),
      }),
    )[0]!;

  it('separates a signature discarded by a guard from one that was out-competed', () => {
    // The two readings call for different work, and the scalar anomaly score
    // cannot express either — this is the only place they are told apart.
    const dropped = caseWith('JVMMemoryStress', [
      {
        serviceId: 'ts-a',
        dominant: 'k8s.pod.filesystem.usage',
        metricOutcomes: [{ label: 'container.memory.rss', outcome: 'transient-return', score: 0 }],
      },
    ]);
    const outcompeted = caseWith('JVMMemoryStress', [
      {
        serviceId: 'ts-b',
        dominant: 'k8s.pod.filesystem.usage',
        metricOutcomes: [
          { label: 'container.memory.rss', outcome: 'kept', score: 0.2 },
          { label: 'k8s.pod.filesystem.usage', outcome: 'kept', score: 0.9 },
        ],
      },
    ]);

    const [cell] = familyCompetition([dropped, outcompeted], MEMORY);

    expect(cell!.cases).toBe(2);
    expect(cell!.sourcesWithFamily).toBe(2);
    expect(cell!.sourcesKeepingFamily).toBe(1);
    expect(cell!.sourcesDroppingFamily).toBe(1);
    expect(cell!.sourcesKeepingButLosingFamily).toBe(1);
    expect(cell!.sourcesDominantInFamily).toBe(0);
  });

  it('counts the family winning its own service separately from merely surviving', () => {
    const won = caseWith('JVMMemoryStress', [
      {
        serviceId: 'ts-a',
        dominant: 'container.memory.rss',
        metricOutcomes: [{ label: 'container.memory.rss', outcome: 'kept', score: 0.9 }],
      },
    ]);

    const [cell] = familyCompetition([won], MEMORY);

    expect(cell!.sourcesDominantInFamily).toBe(1);
    expect(cell!.sourcesKeepingButLosingFamily).toBe(0);
  });

  it('reports a source that carries no family metric at all as a data gap', () => {
    const absent = caseWith('ContainerKill', [
      {
        serviceId: 'ts-a',
        dominant: 'container.cpu.usage',
        metricOutcomes: [{ label: 'container.cpu.usage', outcome: 'kept', score: 0.9 }],
      },
    ]);

    const [cell] = familyCompetition([absent], MEMORY);

    expect(cell!.sourcesWithoutFamily).toBe(1);
    expect(cell!.sourcesWithFamily).toBe(0);
    expect(cell!.sourcesKeepingFamily).toBe(0);
  });

  it('ignores a service that is not ground truth, and one with no reported inventory', () => {
    const text = dump({
      groundTruthServices: ['ts-source'],
      services: [
        serviceLine({
          serviceId: 'ts-bystander',
          metricOutcomes: [{ label: 'container.memory.rss', outcome: 'kept', score: 0.9 }],
        }),
        serviceLine({ serviceId: 'ts-source' }),
      ],
      topPredictions: ['ts-bystander', 'ts-source'],
    });

    const [cell] = familyCompetition(parseDiagnosticDump(text), MEMORY);

    expect(cell!.cases).toBe(1);
    expect(cell!.sourcesWithFamily).toBe(0);
    expect(cell!.sourcesWithoutFamily).toBe(0);
  });

  it('counts every case once even when a global pattern is supplied', () => {
    // `test` on a global regex advances `lastIndex`, so a naive reducer answers
    // differently on alternate calls and silently halves its counts.
    const global = { label: 'memory', pattern: /memory/gi };
    const one = caseWith('JVMMemoryStress', [
      {
        serviceId: 'ts-a',
        dominant: 'container.memory.rss',
        metricOutcomes: [{ label: 'container.memory.rss', outcome: 'kept', score: 0.9 }],
      },
    ]);

    const [cell] = familyCompetition([one, one, one], global);

    expect(cell!.cases).toBe(3);
    expect(cell!.sourcesWithFamily).toBe(3);
    expect(cell!.sourcesDominantInFamily).toBe(3);
  });

  it('orders cells by case count descending', () => {
    const small = caseWith('JVMException', [{ serviceId: 'ts-a' }]);
    const big = caseWith('JVMMemoryStress', [{ serviceId: 'ts-b' }]);

    expect(familyCompetition([small, big, big], MEMORY).map((c) => c.faultType)).toEqual([
      'JVMMemoryStress',
      'JVMException',
    ]);
  });

  it('breaks a case-count tie by fault-type name, so the table is byte-stable', () => {
    const zeta = caseWith('Zeta', [{ serviceId: 'ts-a' }]);
    const alpha = caseWith('Alpha', [{ serviceId: 'ts-b' }]);

    // Both input orders, so both arms of the tie-break are exercised: with two
    // elements the sort calls the comparator exactly once.
    expect(familyCompetition([zeta, alpha], MEMORY).map((c) => c.faultType)).toEqual([
      'Alpha',
      'Zeta',
    ]);
    expect(familyCompetition([alpha, zeta], MEMORY).map((c) => c.faultType)).toEqual([
      'Alpha',
      'Zeta',
    ]);
  });

  it('renders the table with the family verdict columns', () => {
    const report = formatMetricCompetitionReport(
      [
        caseWith('JVMMemoryStress', [
          {
            serviceId: 'ts-a',
            dominant: 'k8s.pod.filesystem.usage',
            metricOutcomes: [
              { label: 'container.memory.rss', outcome: 'duty-cycled-idle', score: 0 },
            ],
          },
        ]),
      ],
      MEMORY,
      'dump.txt',
    );

    expect(report).toContain("FSE'26 metric competition — dump.txt");
    expect(report).toContain('after-mode: logicHttp');
    expect(report).toContain('tracked family: memory');
    expect(report).toContain('JVMMemoryStress');
    expect(report).toContain('has-fam');
    expect(report).toContain('kept-lost');
  });

  it('says so rather than printing an empty table when no block parsed', () => {
    expect(formatMetricCompetitionReport([], MEMORY, 'dump.txt')).toContain(
      'No DIAG blocks were parsed.',
    );
  });
});

describe('parseDiagnosticDump — anomaly shape', () => {
  const BREAKDOWN = {
    deviation: 3.203,
    trend: 0.04,
    cv: 0.048,
    burst: 0,
    riseRatio: 1954,
    dropRatio: 0.02,
    baselineMean: 0.0017,
  };

  const withShape = (spec: ServiceSpec, topPredictions: string[] = [spec.serviceId]) =>
    dump({ services: [serviceLine(spec)], topPredictions });

  it('attaches the decomposition to the kept metric it belongs to', () => {
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [
        { label: 'hubble_p99', outcome: 'kept', score: 3.291, breakdown: BREAKDOWN },
        { label: 'container.cpu.usage', outcome: 'kept', score: 0.358 },
      ],
    });

    const outcomes = parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes!;

    expect(outcomes.find((o) => o.label === 'hubble_p99')!.breakdown).toEqual(BREAKDOWN);
    expect(outcomes.find((o) => o.label === 'container.cpu.usage')!.breakdown).toBeUndefined();
  });

  it('reads a rise ratio and a baseline in scientific notation', () => {
    // Baselines span 1e-4..1e8, so the render is exponential and the reader has
    // to accept it — a parse that silently produced NaN would zero the report.
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [
        {
          label: 'm',
          outcome: 'kept',
          score: 1,
          breakdown: { ...BREAKDOWN, riseRatio: 7481, baselineMean: 1.7e-3 },
        },
      ],
    });

    const b = parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown!;

    expect(b.riseRatio).toBe(7481);
    expect(b.baselineMean).toBe(0.0017);
  });

  it('ignores a shape line that claims more decompositions than it printed', () => {
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [{ label: 'm', outcome: 'kept', score: 1, breakdown: BREAKDOWN }],
    }).replace('metricTop(1):', 'metricTop(3):');

    expect(
      parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown,
    ).toBeUndefined();
  });

  it('ignores a shape line whose kept total disagrees with the inventory', () => {
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [
        { label: 'a', outcome: 'kept', score: 0.9, breakdown: BREAKDOWN },
        { label: 'b', outcome: 'kept', score: 0.5 },
      ],
    }).replace('metricTop(1/2):', 'metricTop(1/7):');

    expect(
      parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown,
    ).toBeUndefined();
  });

  it('ignores a shape line carrying a token it cannot parse', () => {
    // A partially consumed line is worse than an ignored one: the metrics that
    // did parse look like metrics that genuinely carried no decomposition.
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [{ label: 'm', outcome: 'kept', score: 1, breakdown: BREAKDOWN }],
    })
      .split('\n')
      .map((line) => (line.startsWith('    metricTop(') ? `${line} unparseable` : line))
      .join('\n');

    expect(
      parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown,
    ).toBeUndefined();
  });

  it('ignores a shape line carrying a non-finite value', () => {
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [{ label: 'm', outcome: 'kept', score: 1, breakdown: BREAKDOWN }],
    }).replace('rise=1.954e+3', 'rise=nonfinite');

    expect(
      parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown,
    ).toBeUndefined();
  });

  it('carries four significant digits, which is what the floor comparison needs', () => {
    // The renderer is deliberately compact, so the reader must know what
    // precision it is reading. Four significant digits is the contract, and it
    // is not arbitrary: the baseline column is compared against the near-zero
    // guard's 0.001 floor, and 1.004e-3 must not read back as at-the-floor.
    const text = withShape({
      serviceId: 'ts-order-service',
      metricOutcomes: [
        {
          label: 'm',
          outcome: 'kept',
          score: 1,
          breakdown: { ...BREAKDOWN, riseRatio: 7481.7, baselineMean: 0.001004 },
        },
      ],
    });

    const b = parseDiagnosticDump(text)[0]!.services[0]!.metricOutcomes![0]!.breakdown!;

    expect(b.riseRatio).toBe(7482);
    expect(b.baselineMean).toBe(1.004e-3);
    expect(b.baselineMean).toBeGreaterThan(0.001);
  });
});

describe('anomalyShape', () => {
  const BREAKDOWN = {
    deviation: 3.2,
    trend: 0.04,
    cv: 0.048,
    burst: 0,
    riseRatio: 1954,
    dropRatio: 0.02,
    baselineMean: 0.0017,
  };
  const parse = (
    groundTruthServices: string[],
    services: ServiceSpec[],
    topPredictions: string[],
  ) =>
    parseDiagnosticDump(
      dump({ groundTruthServices, services: services.map(serviceLine), topPredictions }),
    );

  it('separates the source population from the wrong winner', () => {
    // A verdict needs a control: without the source column, "the winner is
    // rise-led" has nothing to be compared against.
    const cases = parse(
      ['ts-source'],
      [
        {
          serviceId: 'ts-source',
          metricOutcomes: [
            {
              label: 'container.memory.rss',
              outcome: 'kept',
              score: 0.78,
              breakdown: { ...BREAKDOWN, deviation: 0.78, riseRatio: 4.9, dropRatio: 0.01 },
            },
          ],
        },
        {
          serviceId: 'ts-winner',
          metricOutcomes: [
            {
              label: 'hubble_p99',
              outcome: 'kept',
              score: 3.291,
              breakdown: { ...BREAKDOWN, baselineMean: 4e-4 },
            },
          ],
        },
      ],
      ['ts-winner', 'ts-source'],
    );

    const cells = anomalyShape(cases);

    const source = cells.find((c) => c.population === 'ground-truth source')!;
    const winner = cells.find((c) => c.population === 'wrong top-1 winner')!;
    expect(source.services).toBe(1);
    expect(source.medianRiseRatio ?? -1).toBe(4.9);
    expect(source.medianBaselineMean).toBe(0.0017);
    expect(source.baselineAtFloor).toBe(0);
    expect(winner.services).toBe(1);
    expect(winner.medianRiseRatio).toBe(1954);
    expect(winner.rise).toBe(1);
    expect(winner.baselineAtFloor).toBe(1);
  });

  it('counts a drop as a drop, and gives it no rise credit', () => {
    const cases = parse(
      ['ts-source'],
      [
        {
          serviceId: 'ts-source',
          metricOutcomes: [
            {
              label: 'mem',
              outcome: 'kept',
              score: 0.301,
              breakdown: { ...BREAKDOWN, deviation: 0.301, riseRatio: 0.01, dropRatio: 1 },
            },
          ],
        },
      ],
      ['ts-source'],
    );

    const source = anomalyShape(cases).find((c) => c.population === 'ground-truth source')!;

    expect(source.drop).toBe(1);
    expect(source.rise).toBe(0);
    expect(source.medianBaselineMean).toBeCloseTo(0.0017, 6);
  });

  it('counts a bonus-led metric separately from a deviation-led one', () => {
    // The bonuses are bounded and the rise is not, so a metric that won on a
    // bonus is a different defect from one that won on a deviation.
    const cases = parse(
      ['ts-source'],
      [
        {
          serviceId: 'ts-source',
          metricOutcomes: [
            {
              label: 'flat',
              outcome: 'kept',
              score: 0.4,
              breakdown: {
                ...BREAKDOWN,
                deviation: 0.1,
                trend: 0.3,
                cv: 0.05,
                burst: 0.04,
                riseRatio: 1.2,
                dropRatio: 0.01,
              },
            },
          ],
        },
      ],
      ['ts-source'],
    );

    const source = anomalyShape(cases).find((c) => c.population === 'ground-truth source')!;

    expect(source.bonusLed).toBe(1);
    expect(source.deviationLed).toBe(0);
  });

  it('excludes a service whose decisive metric has no decomposition', () => {
    const cases = parse(
      ['ts-source'],
      [{ serviceId: 'ts-source', metricOutcomes: [{ label: 'a', outcome: 'kept', score: 1 }] }],
      ['ts-source'],
    );

    expect(anomalyShape(cases).every((c) => c.services === 0)).toBe(true);
  });

  it('reports how each population composed its score', () => {
    // The point of the composition columns: the SAME term leading in both
    // populations means the winner has more of it, not a different one, and no
    // reweighting of that term separates them. A bonus-led winner against a
    // deviation-led source would be the opposite finding.
    const cases = parse(
      ['ts-src'],
      [
        {
          serviceId: 'ts-src',
          metricOutcomes: [
            {
              label: 'mem',
              outcome: 'kept',
              score: 0.4,
              breakdown: {
                ...BREAKDOWN,
                deviation: 0.29,
                trend: 0.1,
                cv: 0.008,
                burst: 0,
                riseRatio: 4.9,
                dropRatio: 0.01,
              },
            },
          ],
        },
        {
          serviceId: 'ts-w',
          metricOutcomes: [
            {
              label: 'hubble_p99',
              outcome: 'kept',
              score: 1,
              breakdown: {
                ...BREAKDOWN,
                deviation: 0.1,
                trend: 0.8,
                cv: 0.05,
                burst: 0.05,
                riseRatio: 1.26,
                dropRatio: 0.01,
              },
            },
          ],
        },
      ],
      ['ts-w', 'ts-src'],
    );

    const cells = anomalyShape(cases);
    const source = cells.find((c) => c.population === 'ground-truth source')!;
    const winner = cells.find((c) => c.population === 'wrong top-1 winner')!;

    expect(source.medianDeviationShare).toBeCloseTo(0.725, 3);
    expect(source.medianTrendShare).toBeCloseTo(0.25, 3);
    expect(source.trendHeavy).toBe(1);
    expect(winner.medianDeviationShare).toBeCloseTo(0.1, 3);
    expect(winner.medianTrendShare).toBeCloseTo(0.8, 3);
    expect(winner.medianCvShare).toBeCloseTo(0.05, 3);
    expect(winner.medianBurstShare).toBeCloseTo(0.05, 3);
    expect(winner.trendHeavy).toBe(1);
    expect(formatAnomalyShapeReport(cases, 'dump.txt')).toContain(
      'How those scores were composed (median share of the score):',
    );
  });

  it('leaves the composition columns blank for a population with no members', () => {
    const cases = parse(['ts-src'], [{ serviceId: 'ts-src' }], ['ts-src']);
    const report = formatAnomalyShapeReport(cases, 'dump.txt');

    expect(report).toContain('trend>=25%');
    // n=0, dev, trend, cv, burst and the count all render as placeholders/zero.
    expect(report).toMatch(/\n {2}wrong top-1 winner\s+0\s+-\s+-\s+-\s+-\s+0\n/);
  });

  it('skips a service the block never rendered an inventory for', () => {
    // A case has ~51 services and only the ground truth and the predictions are
    // rendered, so "no inventory" is the common case and must read as
    // unattributable rather than as an empty competition.
    const cases = parse(
      ['ts-source', 'ts-source-2'],
      [
        { serviceId: 'ts-source' },
        {
          serviceId: 'ts-source-2',
          metricOutcomes: [{ label: 'm', outcome: 'kept', score: 1, breakdown: BREAKDOWN }],
        },
      ],
      ['ts-source', 'ts-source-2'],
    );

    expect(anomalyShape(cases).find((c) => c.population === 'ground-truth source')!.services).toBe(
      1,
    );
  });

  it('renders the profile with every population and the floor column', () => {
    const cases = parse(
      ['ts-source'],
      [
        {
          serviceId: 'ts-source',
          metricOutcomes: [{ label: 'm', outcome: 'kept', score: 1, breakdown: BREAKDOWN }],
        },
      ],
      ['ts-source'],
    );

    const report = formatAnomalyShapeReport(cases, 'dump.txt');

    expect(report).toContain("FSE'26 anomaly shape — dump.txt");
    expect(report).toContain('ground-truth source');
    expect(report).toContain('wrong top-1 winner');
    expect(report).toContain('other predicted / bystander');
    expect(report).toContain('base<=1e-3');
    expect(report).toContain('services with an attributable metric: 1');
  });

  it('renders an empty profile for a dump with no competition', () => {
    expect(formatAnomalyShapeReport([], 'dump.txt')).toContain(
      'services with an attributable metric: 0',
    );
  });

  it('attributes a predicted non-winner to its own population and renders a zero magnitude', () => {
    // A rank-2 prediction is rendered but is neither the ground truth nor the
    // top-1, so it must land in the third population rather than being silently
    // folded into one of the other two. Its decisive metric is a pure drop with
    // a zero rise, which is also the only way the report shows a zero median.
    const cases = parse(
      ['ts-src'],
      [
        {
          serviceId: 'ts-src',
          metricOutcomes: [
            {
              label: 'mem',
              outcome: 'kept',
              score: 1,
              breakdown: { ...BREAKDOWN, riseRatio: 0, dropRatio: 3 },
            },
          ],
        },
        {
          serviceId: 'ts-w',
          metricOutcomes: [{ label: 'w', outcome: 'kept', score: 2, breakdown: BREAKDOWN }],
        },
        {
          serviceId: 'ts-third',
          metricOutcomes: [
            {
              label: 't',
              outcome: 'kept',
              score: 0.5,
              breakdown: { ...BREAKDOWN, riseRatio: 0, baselineMean: 0.5 },
            },
          ],
        },
      ],
      ['ts-w', 'ts-third', 'ts-src'],
    );

    const cells = anomalyShape(cases);
    expect(cells.find((c) => c.population === 'other predicted / bystander')!.services).toBe(1);

    // n=1, dev-led=1, bonus-led=0, rise=0, drop=1, med-rise=0, med-base=0.50, floor=0.
    expect(formatAnomalyShapeReport(cases, 'dump.txt')).toMatch(
      /\n {2}other predicted \/ bystander\s+1\s+1\s+0\s+0\s+1\s+0\s+0\.50\s+0\n/,
    );
  });
});

describe('classifyMiss', () => {
  /**
   * One case whose Top@1 is wrong, parameterised by the two scored terms.
   *
   * The source is always `ts-src` and the winner always `ts-win`, so a reader can
   * see at a glance which term the fixture moved.
   */
  function wrongCase(
    source: { selfAnomaly: number; logScore: number; logic?: number },
    winner: { selfAnomaly: number; logScore: number; logic?: number },
  ) {
    return parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({ serviceId: 'ts-src', ...source }),
          serviceLine({ serviceId: 'ts-win', ...winner }),
        ],
        topPredictions: ['ts-win', 'ts-src'],
      }),
    )[0]!;
  }

  it('attributes nothing when Top@1 is already correct', () => {
    const kase = parseDiagnosticDump(
      dump({
        services: [
          serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 1 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.2 }),
        ],
        topPredictions: ['ts-order-service', 'ts-win'],
      }),
    )[0]!;
    expect(classifyMiss(kase, { logWeight: 1 })).toEqual([]);
  });

  it('attributes a loss to the METRIC term when only the anomaly is higher', () => {
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 0.4, logScore: 0 }, { selfAnomaly: 0.9, logScore: 0 }),
      { logWeight: 1 },
    );
    expect(miss!.decidedBy).toBe('metric');
    expect(miss!.source).toBe('ts-src');
    expect(miss!.winner).toBe('ts-win');
  });

  it('attributes a loss to the LOG term when only the log score is higher', () => {
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 0.8, logScore: 0 }, { selfAnomaly: 0.8, logScore: 1 }),
      { logWeight: 1 },
    );
    expect(miss!.decidedBy).toBe('log');
  });

  it('names the pair when each of the two error terms points at the winner', () => {
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 0.3, logScore: 0 }, { selfAnomaly: 0.9, logScore: 1 }),
      { logWeight: 1 },
    );
    expect(miss!.decidedBy).toBe('metric+log');
  });

  it('reports a TIE when the two scored terms are equal', () => {
    // Equal terms mean the deterministic service-id tiebreak decided the order.
    // That is a missing discrimination, not a signal pointing the wrong way, and
    // the report has to keep the two apart.
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 0.5, logScore: 0.4 }, { selfAnomaly: 0.5, logScore: 0.4 }),
      { logWeight: 1 },
    );
    expect(miss!.decidedBy).toBe('tie');
  });

  it('reports UNEXPLAINED when the winner scores strictly LOWER', () => {
    // The engine ordered a service below one with a strictly higher score. No
    // modelling story explains that, so the category exists to make a bug
    // impossible to mistake for a result.
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 1, logScore: 1 }, { selfAnomaly: 0.1, logScore: 0 }),
      { logWeight: 1 },
    );
    expect(miss!.decidedBy).toBe('unexplained');
  });

  it('scales the log term by the weight it is given', () => {
    // A log gap of 0.2 is enough to overturn a small metric gap at weight 1 and
    // not at weight 0.1 — which is why the CLI makes the weight a value rather
    // than a default.
    const kase = wrongCase({ selfAnomaly: 0.5, logScore: 0 }, { selfAnomaly: 0.4, logScore: 0.2 });
    expect(classifyMiss(kase, { logWeight: 1 })[0]!.decidedBy).toBe('log');
    expect(classifyMiss(kase, { logWeight: 0.1 })[0]!.decidedBy).toBe('unexplained');
  });

  it('reports ABSENT for a dump with no ground truth at all', () => {
    // `GT=[]` is what a case with an unresolvable label produces. There is no
    // source to attribute against, so the case is unattributable rather than
    // attributed to the empty string.
    const kase = parseDiagnosticDump(
      dump({
        groundTruthServices: [],
        services: [serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9 })],
        topPredictions: ['ts-win'],
      }),
    )[0]!;
    const [miss] = classifyMiss(kase, { logWeight: 1 });
    expect(miss!.decidedBy).toBe('absent');
    expect(miss!.source).toBe('');
    expect(Number.isNaN(miss!.sourceAnomaly)).toBe(true);
  });

  it('reports ABSENT for a dump with no prediction at all', () => {
    // `prediction=[]` is a case the engine returned nothing for. There is no
    // winner to score against, and reading the winner's terms as 0 would
    // fabricate the comparison.
    const kase = parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-src'],
        services: [serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.4 })],
        topPredictions: [],
      }),
    )[0]!;
    const [miss] = classifyMiss(kase, { logWeight: 1 });
    expect(miss!.decidedBy).toBe('absent');
    expect(miss!.winner).toBeUndefined();
    expect(Number.isNaN(miss!.winnerAnomaly)).toBe(true);
    expect(miss!.sourceAnomaly).toBe(0.4);
  });

  it('detects a weight that is not the one the run used', () => {
    // A dump's ORDER is only consistent with the weight that produced it, so
    // passing a different weight does not yield a different attribution — it
    // yields `unexplained`, because at that weight the winner scores strictly
    // lower than the source and no ranking could have produced this dump.
    //
    // That is the property that makes `unexplained` worth its own category: a
    // report full of them means the weight handed to the analyzer is wrong, not
    // that the signal is.
    const kase = wrongCase({ selfAnomaly: 0.5, logScore: 0 }, { selfAnomaly: 0.4, logScore: 0.2 });

    // At the run's own weight the loss is fully explained by the log term.
    expect(classifyMiss(kase, { logWeight: 1 })[0]!.decidedBy).toBe('log');
    // At any weight too small to explain it, the same dump reads as inconsistent.
    expect(classifyMiss(kase, { logWeight: 0.1 })[0]!.decidedBy).toBe('unexplained');
  });

  it('reports ABSENT when the source is not in the dump at all', () => {
    // A source the engine never scored is an anomaly-detection or coverage
    // question; nothing about its evidence can be read from this dump.
    const kase = parseDiagnosticDump(
      dump({
        services: [serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9 })],
        topPredictions: ['ts-win'],
      }),
    )[0]!;
    const [miss] = classifyMiss(kase, { logWeight: 1 });
    expect(miss!.decidedBy).toBe('absent');
    expect(Number.isNaN(miss!.sourceAnomaly)).toBe(true);
  });

  it('reports ABSENT, with NaN rather than zero, when the WINNER is not described', () => {
    // A hand-edited or truncated dump can name a winner it does not describe.
    // Reporting 0 for that winner's terms would read as "scored and credited
    // nothing" and would silently attribute the loss to the other term.
    const tampered = dump({
      groundTruthServices: ['ts-src'],
      services: [serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.4 })],
      topPredictions: ['ts-win'],
    });
    const [miss] = classifyMiss(parseDiagnosticDump(tampered)[0]!, { logWeight: 1 });

    expect(miss!.decidedBy).toBe('absent');
    expect(miss!.winner).toBe('ts-win');
    expect(Number.isNaN(miss!.winnerAnomaly)).toBe(true);
    expect(Number.isNaN(miss!.winnerLog)).toBe(true);
    // The source IS described, so its own terms are still reported.
    expect(miss!.sourceAnomaly).toBe(0.4);
  });

  it('flags whether each side emitted error evidence', () => {
    // The silent-source question: a miss where NEITHER side emits cannot be moved
    // by reweighting the log signal, so the report counts them apart.
    const [miss] = classifyMiss(
      wrongCase({ selfAnomaly: 0.4, logScore: 0, logic: 0 }, { selfAnomaly: 0.9, logScore: 0 }),
      { logWeight: 1 },
    );
    expect(miss!.sourceEmits).toBe(false);
    expect(miss!.winnerEmits).toBe(false);

    const [emitting] = classifyMiss(
      wrongCase({ selfAnomaly: 0.4, logScore: 0, logic: 3 }, { selfAnomaly: 0.9, logScore: 0 }),
      { logWeight: 1 },
    );
    expect(emitting!.sourceEmits).toBe(true);
  });
});

describe('the attribution vocabulary is a census, not a sample', () => {
  const TERMS = ['metric', 'log', 'lat', 'pool'];

  it('lists every subset of the four terms, so a label cannot be printed and dropped', () => {
    // `classifyMiss` builds its label by joining the positive parts, so the set of
    // spellings is a FUNCTION of the term list. A spelling reachable that way and
    // absent from the vocabulary would be a label the per-type line prints and the
    // tally silently drops — and nothing would fail, which is the whole risk.
    const subsets: string[] = [];
    for (let mask = 1; mask < 1 << TERMS.length; mask++) {
      subsets.push(
        TERMS.filter((_, index) => (mask & (1 << index)) !== 0)
          .join('+')
          .replace(/^/, ''),
      );
    }

    expect([...MISS_DECIDED_BY].sort()).toEqual([...subsets].sort());
    expect(MISS_DECIDED_BY).toHaveLength(15);
  });

  it('tallies every kind in the vocabulary, in the vocabulary’s own order', () => {
    // Two lists again, and this is the one that decides what the report shows: the
    // tally iterates the ORDER and skips zero counts. A spelling missing here would be
    // counted into `byDecidedBy` and never printed.
    expect(MISS_ORDER.slice(0, MISS_DECIDED_BY.length)).toEqual([...MISS_DECIDED_BY]);
    expect(new Set(MISS_ORDER).size).toBe(MISS_ORDER.length);
    // The three that are not a set of terms come last, so the terms read as a block.
    expect(MISS_ORDER.slice(MISS_DECIDED_BY.length)).toEqual(['tie', 'unexplained', 'absent']);
  });
});

describe('formatMissReport', () => {
  it('tallies every kind, the silent block, and each fault type', () => {
    const text = dump({
      faultType: 'JVMMemoryStress',
      groundTruthServices: ['ts-src'],
      services: [
        // metric-decided, both sides silent
        serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.4 }),
        serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9 }),
      ],
      topPredictions: ['ts-win', 'ts-src'],
    });
    const cases = parseDiagnosticDump(text);
    const report = formatMissReport(cases, { logWeight: 1 });

    expect(report).toContain('wrong cases: 1');
    // Whitespace-insensitive: the column width is presentation, the TALLY is the
    // assertion, and pinning the padding would make a reformat look like a defect.
    expect(report).toMatch(/\n {2}metric\s+1\n/);
    expect(report).toContain('silent both sides (no error evidence either side): 1');
    // The per-type row is the report's last line, and the report deliberately
    // carries no trailing newline, so the anchor is `$` and not `\n`.
    expect(report).toMatch(/JVMMemoryStress\s+wrong=1 silent=1 metric=1$/);
  });

  it('says nothing about kinds that did not occur', () => {
    // A zero row is noise in a report that is read to decide what to fix next.
    const cases = parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.4 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9 }),
        ],
        topPredictions: ['ts-win', 'ts-src'],
      }),
    );
    const report = formatMissReport(cases, { logWeight: 1 });
    expect(report).not.toContain('unexplained');
    expect(report).not.toContain('absent');
  });

  it('accumulates several wrong cases of the same fault type', () => {
    // The first case of a type creates the bucket and the rest append to it; a
    // report that only ever saw one case per type would have an untested append.
    const one = dump({
      datapack: 'dp-1',
      faultType: 'ContainerKill',
      groundTruthServices: ['ts-src'],
      services: [
        serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.4 }),
        serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9 }),
      ],
      topPredictions: ['ts-win', 'ts-src'],
    });
    const two = one.replace('datapack=dp-1', 'datapack=dp-2');
    const report = formatMissReport(parseDiagnosticDump(one + two), { logWeight: 1 });

    expect(report).toContain('wrong cases: 2');
    expect(report).toMatch(/ContainerKill\s+wrong=2 silent=2 metric=2/);
  });

  it('reports zero wrong cases for a dump whose every case is correct', () => {
    const cases = parseDiagnosticDump(
      dump({
        services: [serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 1 })],
        topPredictions: ['ts-order-service'],
      }),
    );
    const report = formatMissReport(cases, { logWeight: 1 });
    expect(report).toContain('wrong cases: 0');
    expect(report).toContain('silent both sides (no error evidence either side): 0');
  });
});

describe('caseWeightInterval', () => {
  /** A case from plain numbers, so each fixture reads as arithmetic. */
  const affine = (
    targets: string | readonly string[],
    scores: Record<string, [number, number]>,
  ): WeightSeparationCase => ({
    datapack: 'dp-1',
    targets: typeof targets === 'string' ? [targets] : targets,
    scores: new Map(Object.entries(scores).map(([id, [base, slope]]) => [id, { base, slope }])),
  });

  it('floors the weight when the target trails at rest but rises faster', () => {
    // Target overtakes at base gap 0.3 / slope gap 1 = 0.3.
    const intervals = caseWeightInterval(affine('src', { src: [0, 1], win: [0.3, 0] }));
    expect(intervals).toHaveLength(1);
    expect(intervals[0]!.min).toBeCloseTo(0.3, 10);
    expect(intervals[0]!.max).toBe(Number.POSITIVE_INFINITY);
  });

  it('caps the weight when the target leads at rest but rises slower', () => {
    // The competitor overtakes at 0.2 / 0.5 = 0.4.
    const intervals = caseWeightInterval(affine('src', { src: [0.5, 0.5], win: [0.3, 1] }));
    expect(intervals[0]!.min).toBe(0);
    expect(intervals[0]!.max).toBeCloseTo(0.4, 10);
  });

  it('is unsatisfiable when an equal-slope competitor is ahead at rest', () => {
    // No weight changes the gap, so the target can never be rank 1. Reported as an
    // empty interval rather than a huge number, which a caller could mistake for a
    // satisfiable constraint.
    expect(caseWeightInterval(affine('src', { src: [1, 2], win: [1.5, 2] }))).toEqual([]);
  });

  it('is unbounded when no competitor rises faster', () => {
    const intervals = caseWeightInterval(
      affine('src', { src: [0.5, 5], win: [0.1, 1], third: [0.2, 2] }),
    );
    expect(intervals).toEqual([{ min: 0, max: Number.POSITIVE_INFINITY }]);
  });

  it('excludes every weight when the target is not in the dump', () => {
    expect(caseWeightInterval(affine('absent', { other: [1, 0] }))).toEqual([]);
  });

  it('accepts ANY of the case labels as a root, not just the first', () => {
    // `src` can never be first — `win` matches its slope and leads at rest — but
    // `other` can. The benchmark labels list both, so the case is satisfied.
    // Reading `groundTruth[0]` alone reported exactly this shape as unsatisfiable
    // for 42 of 97 `NetworkPartition` cases in a measured dump.
    const intervals = caseWeightInterval(
      affine(['src', 'other'], { src: [1, 2], win: [1.5, 2], other: [2, 5] }),
    );

    expect(intervals).toEqual([{ min: 0, max: Number.POSITIVE_INFINITY }]);
  });

  it('MERGES two roots ranges that touch, so the result stays a set of maxima', () => {
    // `b` is first up to 0.375 and `a` from 0.375, so together they cover every
    // weight from 0. Each root alone is bounded, so a version that returned the
    // roots' ranges without merging would report two intervals here — and a caller
    // asking whether a weight is feasible would still get the right answer, which
    // is exactly why this needs its own test rather than being implied by the
    // disjoint case.
    const intervals = caseWeightInterval(
      affine(['a', 'b'], { a: [0.4, 3], b: [1.9, -1], c: [0.5, 0] }),
    );

    expect(intervals).toEqual([{ min: 0, max: Number.POSITIVE_INFINITY }]);
  });

  it('keeps two roots DISJOINT ranges disjoint, not one hull over the gap', () => {
    // `a` is first only up to 0.1/3, `b` only from 0.7/3, and `c` owns the gap
    // between them. Reporting the hull `[0, Infinity]` would claim the gap, so a
    // caller reading it as feasible would measure a weight with no evidence.
    const intervals = caseWeightInterval(
      affine(['a', 'b'], { a: [0.2, 3], b: [1.0, -3], c: [0.9, 0] }),
    );

    expect(intervals).toHaveLength(2);
    expect(intervals[0]!.min).toBe(0);
    expect(intervals[0]!.max).toBeCloseTo(0.1 / 3, 10);
    expect(intervals[1]!.min).toBeCloseTo(0.7 / 3, 10);
    expect(intervals[1]!.max).toBe(Number.POSITIVE_INFINITY);
  });
});

describe('computeWeightSeparation', () => {
  const one = (
    name: string,
    targets: string | readonly string[],
    scores: Record<string, [number, number]>,
  ) => ({
    datapack: name,
    targets: typeof targets === 'string' ? [targets] : targets,
    scores: new Map(Object.entries(scores).map(([id, [base, slope]]) => [id, { base, slope }])),
  });

  it('is NOT satisfiable by a weight the extremes alone would allow', () => {
    // The first case accepts either root, over two DISJOINT ranges with `c` owning
    // the gap; the second accepts only `[0.1, 0.2]`, which is inside that gap. The
    // extremes are `requiredMin = 0.1` and `allowedMax = 0.2`, so a rule of
    // "requiredMin <= allowedMax" would call this separable and send someone to
    // measure a weight that no case can accept.
    const gapped = one('dp-gap', ['a', 'b'], { a: [0.2, 3], b: [1.0, -3], c: [0.9, 0] });
    const middle = one('dp-middle', 'z', { z: [0.5, 1], k: [0.2, 2.5], m: [0.6, 0] });

    const report = computeWeightSeparation([gapped, middle]);

    expect(report.separable).toBe(false);
    expect(report.requiredMin).toBeCloseTo(0.1, 10);
    expect(report.allowedMax).toBeCloseTo(0.2, 10);
  });

  it('is separable when the intervals overlap', () => {
    // dp-a needs >= 0.2/1 = 0.2; dp-b is overtaken at 0.4/1 = 0.4, so it tolerates
    // <= 0.4. The window [0.2, 0.4] is non-empty.
    const report = computeWeightSeparation([
      one('dp-a', 'src', { src: [0, 1], win: [0.2, 0] }),
      one('dp-b', 'src', { src: [0.4, 0], win: [0.2, 1] }),
    ]);
    expect(report.separable).toBe(true);
    expect(report.requiredMin).toBeCloseTo(0.2, 10);
    expect(report.allowedMax).toBeCloseTo(0.2, 10);
    expect(report.bindingMin).toBe('dp-a');
    expect(report.bindingMax).toBe('dp-b');
  });

  it('is NOT separable when the intervals overlap nowhere, and names both binders', () => {
    // The measured shape of the failed-edge axis: the wins need >= 0.6 while the
    // losses cap the weight at 0.3, so no sweep can pass.
    const report = computeWeightSeparation([
      one('needs-a-lot', 'src', { src: [0, 1], win: [0.6, 0] }),
      // Satisfiable on its own, but only up to 0.3 — the target leads at rest and
      // rises more slowly, so (0.5 - 0.2) / (0 - 1) caps it. Two SATISFIABLE cases
      // whose windows do not overlap is the shape this test is about.
      one('breaks-early', 'src', { src: [0.5, 0], win: [0.2, 1] }),
    ]);
    expect(report.separable).toBe(false);
    expect(report.requiredMin).toBeCloseTo(0.6, 10);
    expect(report.allowedMax).toBeCloseTo(0.3, 10);
    expect(report.bindingMin).toBe('needs-a-lot');
    expect(report.bindingMax).toBe('breaks-early');
  });

  it('makes an UNSATISFIABLE case exclude every weight in BOTH bounds', () => {
    // The competitor leads at rest AND rises faster, so no weight makes this target
    // first. The honest bounds are therefore `+Infinity` (no weight is enough) and
    // `-Infinity` (no weight is permitted) — reporting the case's raw lower bound of
    // 0 would suggest w = 0 satisfies it, which is the opposite of what it says.
    const report = computeWeightSeparation([
      one('impossible', 'src', { src: [0.3, 0], win: [0.5, 1] }),
    ]);

    expect(report.separable).toBe(false);
    expect(report.requiredMin).toBe(Number.POSITIVE_INFINITY);
    expect(report.allowedMax).toBe(Number.NEGATIVE_INFINITY);
    expect(report.bindingMin).toBe('impossible');
    expect(report.bindingMax).toBe('impossible');
  });

  it('treats an empty input as trivially separable', () => {
    // No requirement means no constraint; reporting it as inseparable would fail
    // every run that happens to move no case.
    const report = computeWeightSeparation([]);
    expect(report.separable).toBe(true);
    expect(report.cases).toBe(0);
  });
});

describe('buildWeightSeparationCases', () => {
  it('reads the shipped formula: base is log1p(self) plus the log term, slope is the failed-edge score', () => {
    const cases = buildWeightSeparationCases(
      parseDiagnosticDump(
        dump({
          groundTruthServices: ['ts-order-service'],
          services: [
            serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.5, logScore: 0 }),
            serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, logScore: 0, failedEdge: 1 }),
          ],
          topPredictions: ['ts-order-service'],
        }),
      ),
      { logWeight: 1 },
    );

    const target = cases[0]!.scores.get('ts-order-service')!;
    expect(target.base).toBeCloseTo(Math.log1p(0.5), 10);
    expect(target.slope).toBe(0);
    expect(cases[0]!.scores.get('ts-win')!.slope).toBe(1);
  });

  it('skips a case with no ground truth, which has no target to satisfy', () => {
    const cases = buildWeightSeparationCases(
      parseDiagnosticDump(
        dump({ groundTruthServices: [], services: [serviceLine({ serviceId: 'ts-win' })] }),
      ),
      { logWeight: 1 },
    );
    expect(cases).toEqual([]);
  });

  it('treats a dump written before the field existed as a zero slope, not as a gap', () => {
    // An older dump has no `failedEdge=`, and the coefficient of an absent term IS
    // zero — a genuine zero, unlike a missing measurement, because the term simply
    // was not in the score. That is the opposite of the parser's rule for the same
    // field, where absence means "cannot answer" rather than "zero"; here the
    // solver is modelling a score that did not include the term at all.
    const legacy = dump({
      groundTruthServices: ['ts-order-service'],
      services: [
        serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 1, logScore: 0 }),
        serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.5, logScore: 0 }),
      ],
      topPredictions: ['ts-order-service'],
    }).replace(/ failedEdge=\S+ failedEdgeRecords=\d+/, '');

    const cases = buildWeightSeparationCases(parseDiagnosticDump(legacy), { logWeight: 1 });
    expect(cases[0]!.scores.get('ts-win')!.slope).toBe(0);
    expect(computeWeightSeparation(cases).separable).toBe(true);
  });

  it('names BOTH binders when two satisfiable cases want opposite weights', () => {
    // The comparison form is the useful one when both bounds exist: 0.6 is what the
    // gain needs and 0.3 is what the loss tolerates. This is the sentence the
    // failed-edge axis was closed with, so it has to keep saying which case is which.
    // Two dumps CONCATENATED as text and parsed together — the pattern the other
    // multi-case fixtures use. Concatenating the parsed arrays would stringify them.
    const text =
      // The source is behind at rest but carries the case's only measurement, so it
      // needs w >= log1p(2) = 1.099 to overtake.
      dump({
        datapack: 'dp-needs',
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({ serviceId: 'ts-src', selfAnomaly: 0, logScore: 0, latRise: 11 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 2, logScore: 0 }),
        ],
        topPredictions: ['ts-win', 'ts-src'],
      }) +
      // The inverse: the source is ahead at rest and carries NO measurement, so any
      // weight above log1p(0.3) = 0.262 hands rank 1 to the winner.
      dump({
        datapack: 'dp-breaks',
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.3, logScore: 0 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, logScore: 0, latRise: 11 }),
        ],
        topPredictions: ['ts-src', 'ts-win'],
      });

    const report = formatWeightSeparationReport(parseDiagnosticDump(text), { logWeight: 1 }, 'lat');

    expect(report).toContain('separable: NO');
    expect(report).toContain('needs 1.099 for dp-needs');
    expect(report).toContain('before dp-breaks breaks');
  });

  it('names the unsatisfiable case in words, not as a comparison of infinities', () => {
    const report = formatWeightSeparationReport(
      parseDiagnosticDump(
        dump({
          groundTruthServices: ['ts-order-service'],
          services: [
            serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0, logScore: 0 }),
            serviceLine({
              serviceId: 'ts-win',
              selfAnomaly: 0.9,
              logScore: 0,
              failedEdge: 1,
            }),
          ],
          topPredictions: ['ts-order-service'],
        }),
      ),
      { logWeight: 1 },
    );

    // No weight makes this target first (the winner leads at rest and rises
    // faster), so BOTH bounds are non-numeric and the comparison form would print
    // two infinities. The report says what happened instead.
    expect(report).toContain('separable: NO');
    expect(report).toContain('required min weight: none');
    expect(report).toContain('allowed max weight:  none');
    expect(report).toContain('dp-1 admits no weight at all');
    expect(report).not.toContain('Infinity');
  });

  it('scales the log term by the weight it is given', () => {
    const parsed = parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-order-service'],
        services: [
          serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0, logScore: 1 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, logScore: 0 }),
        ],
        topPredictions: ['ts-order-service'],
      }),
    );
    const atOne = buildWeightSeparationCases(parsed, { logWeight: 1 })[0]!;
    const atHalf = buildWeightSeparationCases(parsed, { logWeight: 0.5 })[0]!;
    expect(atOne.scores.get('ts-order-service')!.base).toBeCloseTo(1, 10);
    expect(atHalf.scores.get('ts-order-service')!.base).toBeCloseTo(0.5, 10);
  });
});

describe('formatWeightSeparationReport', () => {
  it('reports both bounds and the verdict, and names no binder when none exists', () => {
    const report = formatWeightSeparationReport(
      parseDiagnosticDump(
        dump({
          groundTruthServices: ['ts-order-service'],
          services: [
            // The target wins at rest AND resists the weight: it has the smaller
            // slope, so raising the weight eventually hands rank 1 to the winner.
            serviceLine({
              serviceId: 'ts-order-service',
              selfAnomaly: 1,
              logScore: 0,
              failedEdge: 1,
            }),
            serviceLine({
              serviceId: 'ts-win',
              selfAnomaly: 0.5,
              logScore: 0,
              failedEdge: 2,
            }),
          ],
          topPredictions: ['ts-order-service'],
        }),
      ),
      { logWeight: 1 },
    );

    // Overtake at (0.405 - 0.693) / (1 - 2) = 0.288, so every weight in
    // [0, 0.288] keeps the target first: a finite cap, and a satisfiable one. The
    // unsatisfiable branch is covered by the separate fixture below.
    expect(report).toContain('separable: YES');
    expect(report).toContain('required min weight: 0.000');
    expect(report).toContain('allowed max weight:  0.288');
    expect(report).toContain('cases the weight is supposed to satisfy: 1');
    // No binding-cases line here: it names the two cases that conflict, and a
    // satisfiable interval has no conflict to name.
    expect(report).not.toContain('binding cases');
  });

  it('distinguishes "no weight works" from "no cap", never collapsing the two', () => {
    // `-Infinity` is what an unsatisfiable case contributes, and printing it as
    // "unbounded" would report the worst case as the most permissive one.
    const report = formatWeightSeparationReport(
      parseDiagnosticDump(
        dump({
          groundTruthServices: ['ts-order-service'],
          services: [
            serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0, logScore: 0 }),
            serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.9, logScore: 0 }),
          ],
          topPredictions: ['ts-order-service'],
        }),
      ),
      { logWeight: 1 },
    );

    expect(report).toContain('separable: NO');
    expect(report).toContain('allowed max weight:  none');
    expect(report).not.toContain('unbounded');
  });

  it('says unbounded rather than printing an infinite bound', () => {
    // `Infinity.toFixed(3)` renders as "Infinity", which reads like a value.
    const report = formatWeightSeparationReport(
      parseDiagnosticDump(
        dump({
          groundTruthServices: ['ts-order-service'],
          services: [
            serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 1, logScore: 0 }),
            serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, logScore: 0 }),
          ],
          topPredictions: ['ts-order-service'],
        }),
      ),
      { logWeight: 1 },
    );

    expect(report).toContain('allowed max weight:  unbounded');
    expect(report).toContain('separable: YES');
    expect(report).not.toContain('Infinity');
  });
});

describe('latencySlopes', () => {
  /** Parse a case whose service lines carry the given latency measurements. */
  const parsed = (services: Parameters<typeof serviceLine>[0][]) =>
    parseDiagnosticDump(dump({ services: services.map(serviceLine) }))[0]!.services;

  it('compresses the rise with log1p and max-normalises it across the case', () => {
    // The dump carries the RAW ratio; the term applies `log1p(max(0, r − 1))` and
    // then divides by the case maximum. Both steps have to be reproduced, or the
    // solver would solve for a term the engine does not compute.
    const slopes = latencySlopes(
      parsed([
        serviceLine({ serviceId: 'ts-a', latRise: 3, latEdges: 1 }),
        serviceLine({ serviceId: 'ts-b', latRise: 11, latEdges: 2 }),
      ]),
    );

    expect(slopes.get('ts-b')).toBe(1);
    expect(slopes.get('ts-a')!).toBeCloseTo(Math.log1p(2) / Math.log1p(10), 12);
  });

  it('omits a service with no measurement rather than giving it a zero', () => {
    // Present-with-0 would claim a measured flat latency. The engine keeps the
    // stronger statement — absent — so the solver has to agree, or it would rank a
    // service the engine does not.
    const slopes = latencySlopes(
      parsed([
        serviceLine({ serviceId: 'ts-a', latRise: 5, latEdges: 1 }),
        serviceLine({ serviceId: 'ts-b' }),
      ]),
    );

    expect(slopes.has('ts-b')).toBe(false);
    expect(slopes.get('ts-a')).toBe(1);
  });

  it('returns an empty map when no measurement carries a RISE', () => {
    // `log1p(max(0, r − 1))` is 0 for `r <= 1`, so there is nothing to normalise
    // against and the term cannot reorder any two services.
    const slopes = latencySlopes(
      parsed([
        serviceLine({ serviceId: 'ts-a', latRise: 0.5, latEdges: 1 }),
        serviceLine({ serviceId: 'ts-b', latRise: 1, latEdges: 1 }),
      ]),
    );

    expect(slopes.size).toBe(0);
  });

  it('returns an empty map when nothing was measured at all', () => {
    expect(latencySlopes(parsed([serviceLine({ serviceId: 'ts-a' })])).size).toBe(0);
  });
});

describe('buildWeightSeparationCases — slope selection', () => {
  const cases = () =>
    parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({
            serviceId: 'ts-src',
            selfAnomaly: 0.4,
            failedEdge: 0.1,
            latRise: 11,
            latEdges: 1,
          }),
          serviceLine({
            serviceId: 'ts-win',
            selfAnomaly: 0.9,
            failedEdge: 0.2,
            latRise: 1.5,
            latEdges: 1,
          }),
        ],
        topPredictions: ['ts-win', 'ts-src'],
      }),
    );

  it('uses the failed-edge score by default, so existing callers are unaffected', () => {
    const [one] = buildWeightSeparationCases(cases(), { logWeight: 1 });

    expect(one!.scores.get('ts-src')!.slope).toBeCloseTo(0.1, 12);
    expect(one!.scores.get('ts-win')!.slope).toBeCloseTo(0.2, 12);
  });

  it('uses the latency slope when asked, and it is a DIFFERENT number', () => {
    // `ts-src` has the case's largest rise, so its normalised slope is 1 — and the
    // failed-edge score it replaces is 0.1. The two cannot be mixed, which is why
    // the slope is a selector rather than a caller-supplied map.
    const [one] = buildWeightSeparationCases(cases(), { logWeight: 1 }, 'lat');

    expect(one!.scores.get('ts-src')!.slope).toBeCloseTo(1, 12);
    expect(one!.scores.get('ts-win')!.slope).toBeCloseTo(Math.log1p(0.5) / Math.log1p(10), 12);
  });

  it('names the slope it solved for, so two reports cannot be confused', () => {
    const lat = formatWeightSeparationReport(cases(), { logWeight: 1 }, 'lat');
    const failedEdge = formatWeightSeparationReport(cases(), { logWeight: 1 });

    expect(lat).toContain('slope=lat');
    expect(failedEdge).toContain('slope=failedEdge');
  });
});

describe('computeZeroRegressionWindow — the question the flip is decided on', () => {
  /**
   * Two cases whose only difference is WHO is ahead at rest.
   *
   * `dp-cap` is CORRECT at w = 0 and loses to a competitor with a larger slope at
   * `log1p(0.5)`, so it caps the window. `dp-gain` is WRONG at w = 0 and takes the
   * lead at `log1p(0.25)`, so it is a gain that the cap decides whether we may
   * collect. Both thresholds are written as `log1p` of the anomaly the fixture sets
   * rather than as a decimal, because the dump prints three decimals and a fixture
   * that assumed more precision would silently test the rounding.
   */
  const capCase = dump({
    datapack: 'dp-cap',
    groundTruthServices: ['ts-src'],
    services: [
      serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.5, failedEdge: 0 }),
      serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, failedEdge: 1 }),
    ],
  });
  const gainCase = dump({
    datapack: 'dp-gain',
    groundTruthServices: ['ts-src'],
    services: [
      serviceLine({ serviceId: 'ts-src', selfAnomaly: 0, failedEdge: 1 }),
      serviceLine({ serviceId: 'ts-win', selfAnomaly: 0.25, failedEdge: 0 }),
    ],
  });
  const build = (text: string) =>
    buildWeightSeparationCases(parseDiagnosticDump(text), { logWeight: 1 });

  it('caps the window at the weight where the first currently-correct case loses', () => {
    // `ts-src` leads at rest by log1p(0.5) and is overtaken once the competitor's
    // slope of 1 closes that gap, so the cap is exact and the binder is named.
    const window = computeZeroRegressionWindow(build(capCase));

    expect(window.satisfied).toBe(1);
    expect(window.cap).toBeCloseTo(Math.log1p(0.5), 12);
    expect(window.capBinder?.datapack).toBe('dp-cap');
  });

  it('explains the cap: which service is overtaken, by whom, and by how much', () => {
    // `lead / slopeGap` IS the cap, so a report that gives the cap without these
    // three numbers cannot say whether any reshaping of the term could move it —
    // which is the only actionable question a cap raises.
    const window = computeZeroRegressionWindow(build(capCase));
    const binder = window.capBinder!;

    expect(binder.target).toBe('ts-src');
    expect(binder.rival).toBe('ts-win');
    expect(binder.lead).toBeCloseTo(Math.log1p(0.5), 12);
    expect(binder.slopeGap).toBeCloseTo(1, 12);
    expect(binder.lead / binder.slopeGap).toBeCloseTo(window.cap, 12);
    // A target with NO latency evidence and a rival at the top of the case is the
    // shape no pointwise reshaping of the term can help: the target's slope is
    // already 0 and the rival's is already 1, so the gap is maximal either way.
    expect(binder.targetSlope).toBe(0);
    expect(binder.rivalSlope).toBe(1);
  });

  it('is unbounded when no currently-correct case can be overtaken', () => {
    const window = computeZeroRegressionWindow(
      build(
        dump({
          datapack: 'dp-safe',
          groundTruthServices: ['ts-src'],
          services: [
            serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.5, failedEdge: 1 }),
            serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, failedEdge: 0 }),
          ],
        }),
      ),
    );

    expect(window.cap).toBe(Number.POSITIVE_INFINITY);
    expect(window.capBinder).toBeUndefined();
  });

  it('takes the INTERSECTION of the caps, not the first or the widest', () => {
    // Two correct cases, one tolerant to 0.4055 and one only to 0.2. The window is
    // the tighter of the two, and the binder has to be the case that set it — a
    // report naming the wrong one sends the next step to the wrong case.
    const text =
      capCase +
      dump({
        datapack: 'dp-tight',
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.25, failedEdge: 0 }),
          serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, failedEdge: 1 }),
        ],
      });
    const window = computeZeroRegressionWindow(build(text));

    expect(window.satisfied).toBe(2);
    expect(window.cap).toBeCloseTo(Math.log1p(0.25), 12);
    expect(window.capBinder?.datapack).toBe('dp-tight');
  });

  it('counts a currently-wrong case as a GAIN only where the window covers it', () => {
    // The same gain is inside the window at 0.25 and outside it at 0.1, so the
    // sample has to be evaluated at the weight asked for rather than once for the
    // whole run — a single "gains" number would be true at one weight and false at
    // the other.
    const cases = build(capCase + gainCase);
    const samples = zeroRegressionSamples(cases, [0, 0.1, 0.25]);

    expect(samples.map((s) => [s.weight, s.correct, s.gained, s.lost])).toEqual([
      [0, 1, 0, 0],
      [0.1, 1, 0, 0],
      [0.25, 2, 1, 0],
    ]);
  });

  it('reports the loss as soon as the weight passes the cap', () => {
    const cases = build(capCase);
    const samples = zeroRegressionSamples(cases, [Math.log1p(0.5) - 1e-9, Math.log1p(0.5) + 1e-9]);

    expect(samples[0]!.lost).toBe(0);
    expect(samples[1]!.lost).toBe(1);
    expect(samples[1]!.correct).toBe(0);
  });

  it('ignores a case that is already wrong and can never be satisfied', () => {
    // THE defect this function exists for. The separation report intersects over
    // EVERY case, so one case that admits no weight at all makes it say "no weight
    // works" — which reads as "the signal is useless" when the useful question, and
    // the one the criterion asks, is whether any case can get WORSE. A case that is
    // already wrong cannot get worse.
    const hopeless = dump({
      datapack: 'dp-hopeless',
      groundTruthServices: ['ts-ghost'],
      services: [serviceLine({ serviceId: 'ts-src', selfAnomaly: 1 })],
    });
    const cases = build(capCase + hopeless);

    expect(computeWeightSeparation(cases).separable).toBe(false);

    const window = computeZeroRegressionWindow(cases);
    expect(window.cap).toBeCloseTo(Math.log1p(0.5), 12);
    expect(window.unreachable).toBe(1);
    expect(window.gains.map((g) => g.datapack)).toEqual([]);
  });

  it('states both questions in the report, so the NO cannot be read as the verdict', () => {
    const hopeless = dump({
      datapack: 'dp-hopeless',
      groundTruthServices: ['ts-ghost'],
      services: [serviceLine({ serviceId: 'ts-src', selfAnomaly: 1 })],
    });
    const report = formatZeroRegressionWindowReport(
      parseDiagnosticDump(capCase + gainCase + hopeless),
      {
        logWeight: 1,
      },
    );

    expect(report).toContain('slope=failedEdge');
    expect(report).toContain('binder dp-cap');
    // The cap is not just a number: the report names the pair and the two quantities
    // whose ratio it is, because "can any reshaping of the term move this cap?"
    // is answered by the competitor's slope and the target's, not by the cap alone.
    expect(report).toContain('ts-win overtakes ts-src');
    expect(report).toMatch(/lead 0\.405465/);
    expect(report).toMatch(/slope gap 1\.000000/);
    // The cap is printed as a number, and the first weight ABOVE it is shown
    // forfeiting a case — the claim is two-sided rather than "zero below the cap".
    expect(report).toMatch(/cap weight:\s+0\.405465/);
    // The claim is two-sided: the row AT the cap still holds every case, and the
    // first row past it forfeits exactly the one named as the binder.
    const rows = [...report.matchAll(/^\s{2}([0-9.]+)\s+(\d+)\s+(\d+)\s+(\d+)(.*)$/gm)].map(
      (m) => ({
        weight: Number(m[1]),
        correct: Number(m[2]),
        lost: Number(m[4]),
        mark: m[5]!.trim(),
      }),
    );
    expect(rows.find((r) => r.mark === '')!.lost).toBe(0);
    expect(rows.find((r) => r.mark !== '')!.lost).toBe(1);
    // And it says which question it answered. `computeWeightSeparation` answers NO
    // on this same input, so a reader who confuses the two reports the signal as
    // unusable when the criterion's question has a YES.
    expect(report).toContain('may become incorrect');
  });

  it('probes the cap itself by default, not only a coarse grid around it', () => {
    // The slope is the dump's own `failedEdge=` column, so the fixtures above model
    // the score they are solving for. The latency slope is a DIFFERENT score and is
    // exercised by `--slope lat` on a real dump, where `latRise=` is present.
    const report = formatZeroRegressionWindowReport(parseDiagnosticDump(capCase), { logWeight: 1 });
    const probed = [...report.matchAll(/^\s{2}([0-9.]+)\s/gm)].map((m) => Number(m[1]));

    // The cap is a solved number, not a grid point, so a report that only printed
    // the grid would never show the boundary it claims.
    expect(probed.some((w) => Math.abs(w - Math.log1p(0.5)) < 1e-6)).toBe(true);
    expect(probed.some((w) => w > Math.log1p(0.5))).toBe(true);
  });
});

describe('latencySlopes — the rise floor', () => {
  /**
   * A floor is the generalisation of the shipped shape, not an addition to it: it
   * asks for a rise to clear a threshold before the term credits anybody, on the
   * theory that a rise of 1.1 is noise and a rise of 40 is a lost service. The
   * parameter exists so the question "is the term crediting services on evidence too
   * thin to mean anything?" is a computation rather than an opinion.
   */
  const parsed = (services: Parameters<typeof serviceLine>[0][]) =>
    parseDiagnosticDump(dump({ services: services.map(serviceLine) }))[0]!.services;
  const three = () =>
    parsed([
      serviceLine({ serviceId: 'ts-big', latRise: 10, latEdges: 1 }),
      serviceLine({ serviceId: 'ts-small', latRise: 3, latEdges: 1 }),
      serviceLine({ serviceId: 'ts-flat', latRise: 0.5, latEdges: 1 }),
    ]);

  it('is byte-identical to the shipped shape at a floor of 1', () => {
    // THE property that makes the floor a usable axis: its boundary is today's
    // behaviour, so every comparison starts from the shipped term rather than from
    // an approximation of it.
    const shipped = latencySlopes(three());
    const atOne = latencySlopes(three(), 1);

    expect([...atOne]).toEqual([...shipped]);
  });

  it('drops a rise below the floor, so the service reads as UNMEASURED', () => {
    // Absent, not zero: a zeroed row would claim a measured flat latency, which is
    // the one reading that means "no evidence" — and it would also keep the service
    // rankable by this term, which is precisely what the floor exists to stop.
    const slopes = latencySlopes(three(), 4);

    expect(slopes.has('ts-small')).toBe(false);
    expect(slopes.get('ts-big')).toBe(1);
  });

  it('keeps a rise at or below 1, which is not evidence of a rise at all', () => {
    // Dropping it would change the shipped shape at the boundary, and the engine's
    // rule is that such a service is present with magnitude 0 — not absent. A floor
    // that silently redefined that would make every floor-1 comparison disagree with
    // the engine on cases that have nothing to do with floors.
    const slopes = latencySlopes(three(), 4);

    expect(slopes.has('ts-flat')).toBe(true);
    expect(slopes.get('ts-flat')).toBe(0);
  });

  it('cannot renormalise: dropping the small rises leaves the maximum where it was', () => {
    // The survivor is always the case maximum, so the divisor is unchanged and the
    // floor is a pure MASK — it deletes votes and never reweights them. That is why
    // a floor can only reduce the term's total effect, and why it cannot remove a
    // spurious competitor without also removing it as a creditee.
    const slopes = latencySlopes(three(), 4);

    expect(slopes.get('ts-big')).toBe(latencySlopes(three()).get('ts-big'));
  });

  it('returns an empty map when the floor is above every rise', () => {
    const slopes = latencySlopes(three(), 11);

    expect(slopes.get('ts-big')).toBeUndefined();
    expect(slopes.size).toBe(0);
  });

  it('carries the floor into the solver, so a window can be solved for it', () => {
    // The solver must reconstruct the term the floor DEFINES, not the shipped one:
    // solving a masked shape's window with the unmasked slopes would report the
    // shipped window under a candidate's name.
    const text = dump({
      datapack: 'dp-floor',
      groundTruthServices: ['ts-src'],
      services: [
        serviceLine({ serviceId: 'ts-src', selfAnomaly: 0.5, latRise: 1.2, latEdges: 1 }),
        serviceLine({ serviceId: 'ts-win', selfAnomaly: 0, latRise: 9, latEdges: 1 }),
      ],
    });
    const atFloor1 = buildWeightSeparationCases(parseDiagnosticDump(text), { logWeight: 1 }, 'lat');
    const atFloor4 = buildWeightSeparationCases(
      parseDiagnosticDump(text),
      { logWeight: 1 },
      'lat',
      4,
    );

    // `ts-src`'s thin rise is dropped, so it has no slope at all under the floor and
    // the only thing that can move the case is the rival's own term.
    expect(atFloor1[0]!.scores.get('ts-src')!.slope).toBeCloseTo(
      Math.log1p(0.2) / Math.log1p(8),
      12,
    );
    expect(atFloor4[0]!.scores.get('ts-src')!.slope).toBe(0);
    expect(atFloor4[0]!.scores.get('ts-win')!.slope).toBe(1);
  });
});

describe('latencySlopes agrees with the engine it predicts', () => {
  /**
   * The solver's whole value depends on this: it reconstructs the term from the
   * dump's `latRise`, while the engine computes it from the raw edges. If the two
   * disagree the predictor is solving a term nobody runs — and the disagreement would
   * be invisible, because both sides are "a number between 0 and 1".
   *
   * The two are fed the SAME evidence in the two shapes the two sides actually see:
   * edges for the engine, `latRise` for the dump. `latRise` is the per-callee
   * maximum of `post / pre`, which is what the engine takes too.
   */
  const EDGES = [
    { caller: 'ui', callee: 'order', preMeanMs: 10, postMeanMs: 300 }, // 30x
    { caller: 'ui', callee: 'pay', preMeanMs: 10, postMeanMs: 105 }, // 10.5x
    { caller: 'gw', callee: 'pay', preMeanMs: 10, postMeanMs: 20 }, // 2x -- pay's max is 10.5x
    { caller: 'gw', callee: 'stock', preMeanMs: 10, postMeanMs: 11 }, // 1.1x
    { caller: 'gw', callee: 'flat', preMeanMs: 10, postMeanMs: 5 }, // got FASTER
  ];
  const nodes = new Set(['ui', 'gw', 'order', 'pay', 'stock', 'flat']);
  const asDump = () =>
    parseDiagnosticDump(
      dump({
        services: [
          serviceLine({ serviceId: 'ui', latEdges: 2 }),
          serviceLine({ serviceId: 'gw', latEdges: 3 }),
          serviceLine({ serviceId: 'order', latRise: 30, latEdges: 1 }),
          serviceLine({ serviceId: 'pay', latRise: 10.5, latEdges: 2 }),
          serviceLine({ serviceId: 'stock', latRise: 1.1, latEdges: 1 }),
          serviceLine({ serviceId: 'flat', latRise: 0.5, latEdges: 1 }),
        ],
      }),
    )[0]!.services;

  it('produces the same slope for every service, in the shipped shape', () => {
    const fromEngine = computeEdgeLatencyScores(EDGES, nodes);
    const fromDump = latencySlopes(asDump());

    expect([...fromEngine.keys()].sort()).toEqual([...fromDump.keys()].sort());
    for (const [id, slope] of fromEngine) {
      expect(fromDump.get(id)).toBeCloseTo(slope, 12);
    }
  });

  it('still agrees once a floor masks evidence on both sides', () => {
    // A floor of 10 masks `stock` (1.1x) and the second edge into `pay` (2x), but it
    // does NOT mask `flat` (0.5x) or `ui`/`gw` (no inbound rise): the carve-out for a
    // rise at or below 1 is present-with-magnitude-0, exactly as the shipped shape has
    // it. Both sides have to implement that boundary the same way — a floor applied on
    // one side only would show up here as a different key set.
    const fromEngine = computeEdgeLatencyScores(EDGES, nodes, 10);
    const fromDump = latencySlopes(asDump(), 10);

    expect([...fromEngine.keys()].sort()).toEqual(['flat', 'order', 'pay']);
    expect([...fromDump.keys()].sort()).toEqual(['flat', 'order', 'pay']);
    expect(fromDump.get('order')).toBeCloseTo(fromEngine.get('order')!, 12);
    expect(fromDump.get('pay')).toBeCloseTo(fromEngine.get('pay')!, 12);
    // `flat` is credited nothing, on both sides.
    expect(fromEngine.get('flat')).toBe(0);
    expect(fromDump.get('flat')).toBe(0);
  });
});

describe('classifyMiss — the pool penalty is a modelled term', () => {
  /**
   * THE second instance of the defect that produced `unexplained 12`: the shipped score
   * gained a fourth term and the attribution still summed three. `unexplained` is
   * documented as "a bug, or a wrong weight — never a result", so a term the engine has
   * on and the classifier does not model manufactures exactly that reading.
   *
   * The pool term is a PENALTY, so its contribution to the winner's margin is
   * `-weight × (indicator(winner) - indicator(source))`: positive when it subtracted
   * from the ROOT (one of the reasons the root lost), negative when it subtracted from
   * the winner (a term already on the root's side, which must NOT be named).
   */
  const wrongCase = (
    src: { selfAnomaly: number; logScore?: number; latRise?: number; dominant?: string },
    win: { selfAnomaly: number; logScore?: number; latRise?: number; dominant?: string },
  ) => {
    const { dominant: srcDominant, ...srcRest } = src;
    const { dominant: winDominant, ...winRest } = win;
    return parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-src'],
        services: [
          serviceLine({
            serviceId: 'ts-src',
            ...srcRest,
            ...(srcDominant === undefined ? {} : { dominant: srcDominant }),
          }),
          serviceLine({
            serviceId: 'ts-win',
            ...winRest,
            ...(winDominant === undefined ? {} : { dominant: winDominant }),
          }),
        ],
        topPredictions: ['ts-win', 'ts-src'],
      }),
    )[0]!;
  };

  it('names the pool term when the penalty is why the root lost', () => {
    // Equal on everything the other three terms see; the ROOT is pool-dominant, so the
    // penalty subtracted from it while the winner kept its whole score.
    const kase = wrongCase(
      { selfAnomaly: 0.8, dominant: POOL_METRIC_PREFIX + 'use_time.max' },
      { selfAnomaly: 0.8, dominant: 'container.cpu.usage' },
    );

    expect(classifyMiss(kase, { logWeight: 1, latWeight: 0 })[0]!.decidedBy).toBe('pool');
  });

  it('spells out the full four-term combination', () => {
    // Every prior points at the winner AND the penalty subtracted from the root: the
    // answer has to name all four, because a reader acting on it needs to know the
    // pool term is implicated too.
    const kase = wrongCase(
      { selfAnomaly: 0.4, logScore: 0, latRise: 1, dominant: POOL_METRIC_PREFIX + 'wait_time.max' },
      { selfAnomaly: 0.9, logScore: 1, latRise: 100, dominant: 'cpu' },
    );

    expect(classifyMiss(kase, { logWeight: 1 })[0]!.decidedBy).toBe('metric+log+lat+pool');
  });

  it('does NOT name the penalty when it worked FOR the root', () => {
    // The winner is pool-dominant, so the penalty subtracted from IT. Naming it here
    // would send a reader to strengthen a term that is already on the root's side.
    const kase = wrongCase(
      { selfAnomaly: 0.4, dominant: 'cpu' },
      { selfAnomaly: 0.9, dominant: POOL_METRIC_PREFIX + 'use_time.max' },
    );

    expect(classifyMiss(kase, { logWeight: 1, latWeight: 0 })[0]!.decidedBy).toBe('metric');
  });

  it('is the three-term view at a weight of zero, and the SHIPPED view by default', () => {
    // The default is the engine's own constant, imported: a default of 0 here would
    // describe an engine that does not exist. The ablation has to be written down.
    const kase = wrongCase(
      { selfAnomaly: 0.8, dominant: POOL_METRIC_PREFIX + 'use_time.max' },
      { selfAnomaly: 0.8, dominant: 'container.cpu.usage' },
    );

    expect(classifyMiss(kase, { logWeight: 1, latWeight: 0 })[0]!.decidedBy).toBe('pool');
    expect(classifyMiss(kase, { logWeight: 1, latWeight: 0, poolWeight: 0 })[0]!.decidedBy).toBe(
      'tie',
    );
  });
});

